import numpy as np
import numba
from numba import stencil, njit
from numba.core.errors import NumbaValueError

# 1D kernel: average of a[-1], a[0], a[1]
@stencil('wrap')
def k1_wrap(a):
    return 0.25 * (a[-1] + a[0] + a[1])

@stencil('nearest')
def k1_nearest(a):
    return 0.25 * (a[-1] + a[0] + a[1])

@stencil('reflect')
def k1_reflect(a):
    return 0.25 * (a[-1] + a[0] + a[1])

@stencil('symmetric')
def k1_symmetric(a):
    return 0.25 * (a[-1] + a[0] + a[1])

@stencil('constant')
def k1_constant(a):
    return 0.25 * (a[-1] + a[0] + a[1])

def ref(a, mode):
    n = len(a)
    out = np.zeros_like(a)
    for i in range(n):
        idxs = []
        for rel in (-1, 0, 1):
            j = i + rel
            if mode == 'wrap':
                idxs.append(a[j % n])
            elif mode == 'nearest':
                idxs.append(a[min(max(j, 0), n-1)])
            elif mode == 'reflect':
                if n == 1:
                    idxs.append(0.0)
                else:
                    p = 2*(n-1)
                    m = j % p
                    idxs.append(a[m if m < n else p-m])
            elif mode == 'symmetric':
                p = 2*n
                m = j % p
                idxs.append(a[m if m < n else p-m-1])
            else:
                if 0 <= j < n:
                    idxs.append(a[j])
                else:
                    idxs.append(0.0)
        out[i] = 0.25 * sum(idxs)
    return out

for mode, k in [('wrap', k1_wrap), ('nearest', k1_nearest),
                ('reflect', k1_reflect), ('symmetric', k1_symmetric),
                ('constant', k1_constant)]:
    for n in [1, 2, 5, 10]:
        a = np.arange(n, dtype=float) + 1
        got = k(a)
        exp = ref(a, mode)
        ok = np.allclose(got, exp)
        print(mode, n, "OK" if ok else "FAIL", got, exp)
        if not ok:
            raise SystemExit(1)
print("1D basic tests passed")
