@stencil('wrap')
def k_wrap(a):
    return a[-1] + a[0] + a[1]

@stencil('reflect')
def k_reflect(a):
    return a[-1] + a[0] + a[1]

@stencil(mode=('reflect', 'nearest'))
def k_mixed(a):
    return a[-1, 0] + a[0, 1]

def ref1(a, mode):
    n = len(a)
    out = np.zeros_like(a)
