            if mode == 'wrap':
                idx = j % n
            elif mode == 'nearest':
                idx = min(max(j, 0), n-1)
            elif mode == 'reflect':
                p = 2*(n-1); m = j % p; idx = m if m < n else p-m
            elif mode == 'symmetric':
                p = 2*n; m = j % p; idx = m if m < n else p-m-1
            s += a[idx]
        out[i] = s
    return out

@njit(parallel=True)
