def k_reflect(a):
    return a[-1] + a[0] + a[1]

@stencil(mode=('reflect', 'nearest'))
def k_mixed(a):
    return a[-1, 0] + a[0, 1]

def ref1(a, mode):
    n = len(a)
    out = np.zeros_like(a)
    for i in range(n):
        s = 0.0
        for rel in (-1, 0, 1):
            j = i + rel
            if mode == 'wrap':
                idx = j % n
            elif mode == 'nearest':
                idx = min(max(j, 0), n-1)
            elif mode == 'reflect':
                p = 2*(n-1); m = j % p; idx = m if m < n else p-m
            elif mode == 'symmetric':
                p = 2*n; m = j % p; idx = m if m < n else p-m-1
